# apl-source:14
#     اطبع "ناجح:", اسم
# apl-source:15

# apl-source:16
def تأكد_يساوي(فعلي, متوقع, اسم):
  # apl-source:17
  if فعلي != متوقع:
    # apl-source:18
    print("فشل:", اسم)
    # apl-source:19
    print("  متوقع:", متوقع)
    # apl-source:20
    print("  فعلي:", فعلي)
    # apl-source:21
    قياسي_نظام_اخرج(1)
  # apl-source:22
  print("ناجح:", اسم)
# apl-source:23

# apl-source:24
# رقم اليوم الجولياني: التحويل في الاتجاهين ويوم الأسبوع
# apl-source:25
# Demonstrates: تحويل تاريخ إلى رقم مطلق, عكسه, فرق الأيام
# apl-source:26
# الفرق بين تاريخين هو مجرد طرح
# apl-source:27

# apl-source:28
def إلى_جولياني(سنة, شهر, يوم):
  # apl-source:29
  أ = (14 - شهر) // 12
  # apl-source:30
  س2 = سنة + 4800 - أ
  # apl-source:31
  ش2 = شهر + 12 * أ - 3
  # apl-source:32
  return يوم + (153 * ش2 + 2) // 5 + 365 * س2 + س2 // 4 - س2 // 100 + س2 // 400 - 32045
# apl-source:33

# apl-source:34
def من_جولياني(ج):
  # apl-source:35
  ل = ج + 68569
  # apl-source:36
  ن = (4 * ل) // 146097
  # apl-source:37
  ل = ل - (146097 * ن + 3) // 4
  # apl-source:38
  ي = (4000 * (ل + 1)) // 1461001
  # apl-source:39
  ل = ل - (1461 * ي) // 4 + 31
  # apl-source:40
  ش = (80 * ل) // 2447
  # apl-source:41
  يوم = ل - (2447 * ش) // 80
  # apl-source:42
  ل = ش // 11
  # apl-source:43
  شهر = ش + 2 - 12 * ل
  # apl-source:44
  سنة = 100 * (ن - 49) + ي + ل
  # apl-source:45
  return [سنة, شهر, يوم]
# apl-source:46

# apl-source:47
def يوم_أسبوع(ج):
  # apl-source:48
  أسماء = ["أحد", "اثنين", "ثلاثاء", "أربعاء", "خميس", "جمعة", "سبت"]
  # apl-source:49
  return أسماء[(ج + 1) % 7]
# apl-source:50

# apl-source:51
تأكد_يساوي(إلى_جولياني(2000, 1, 1), 2451545, "ألفينية")
# apl-source:52
تأكد_يساوي(إلى_جولياني(1970, 1, 1), 2440588, "عصر يونكس")
# apl-source:53
تأكد_يساوي(من_جولياني(2451545), [2000, 1, 1], "العكس ألفينية")
# apl-source:54
تأكد_يساوي(من_جولياني(2440588), [1970, 1, 1], "العكس يونكس")
# apl-source:55
تأكد_يساوي(يوم_أسبوع(2451545), "سبت", "أول 2000 كان سبتا")
# apl-source:56
تأكد_يساوي(يوم_أسبوع(إلى_جولياني(2024, 2, 29)), "خميس", "كبيسة 2024 خميس")
# apl-source:57
تأكد_يساوي(إلى_جولياني(2024, 3, 1) - إلى_جولياني(2024, 2, 1), 29, "فبراير الكبيس 29")
# apl-source:58
عمر = إلى_جولياني(2024, 1, 1) - إلى_جولياني(2000, 9, 9)
# apl-source:59
تأكد_يساوي(عمر, 8514, "فرق تاريخين بالأيام")
# apl-source:60
print("يوم 2000-01-01:", يوم_أسبوع(2451545))
# apl-source:61
